# Executed by build.py with the common page helpers. No network calls.
products=json.loads(read('content/products.json'))
categories={'sports':'Sports / Activity / Exercise','personal':'Personal / Professional / Executive','enterprise':'Enterprise','industrial':'Industrial / Manufacturing / Construction'}
statuses={'untested':'Untested with Vocari','limited':'Limited Vocari test evidence','tested':'Vocari-tested on the listed setup'}
types={'in-ear':'In-ear earbuds','open-ear':'Open-ear','boom':'Boom microphone','hearing-protection':'Hearing protection'}
def product_card(p):
 purchase=p['purchase']; placement='catalogcard'
 destination=purchase.get('placements',{}).get(placement,purchase['url'])
 if not destination.startswith('https://'): raise ValueError('Product destinations must use HTTPS')
 if purchase['affiliate'] and not purchase.get('network'): raise ValueError('Affiliate links require an approved network')
 if p['testStatus'] not in statuses: raise ValueError('Unknown test status')
 if p['testStatus']!='untested' and not all(p.get('testEvidence',{}).get(key) for key in ['date','summary','url']): raise ValueError('Testing claims require dated evidence and a report URL')
 rel='sponsored noopener' if purchase['affiliate'] else 'noopener'
 photo=p.get('image')
 if photo:
  if p['imagePermission']['status']!='approved' or not p['imagePermission'].get('grant'): raise ValueError('Missing image license for '+p['id'])
  visual=f'<img src="{esc(photo["src"])}" width="{photo["width"]}" height="{photo["height"]}" alt="{esc(photo["alt"])}" loading="lazy">'
 else:
  visual=f'<span class="photo-brand">{esc(p["brand"])}</span><span class="photo-style">{esc(types[p["type"]])}</span><a href="{esc(p["sources"][0])}" class="photo-link" aria-label="View manufacturer photos of {esc(p["brand"]+" "+p["name"])}">View manufacturer photos <span aria-hidden="true">↗</span></a>'
 evidence=''
 if p['testStatus']!='untested':
  e=p['testEvidence']
  if not e['url'].startswith(('https://','/')): raise ValueError('Invalid evidence URL')
  evidence=f'<p class="source-note"><strong>Vocari evidence · {esc(e["date"])}</strong><br>{esc(e["summary"])} <a href="{esc(e["url"])}">Test setup and limitations ↗</a></p>'
 feats=''.join('<li>'+esc(f)+'</li>' for f in p['features'])
 details=f'<details class="product-details"><summary>Before you choose</summary><div>{esc(p["consideration"])}<p class="source-note">Manufacturer information checked September 16, 2026. <a href="{esc(p["sources"][-1])}">Read the source ↗</a></p></div></details>'
 return f'''<article class="product-card" id="{esc(p['id'])}" data-product="{esc(p['id'])}" data-categories="{' '.join(p['categories'])}" data-type="{p['type']}" data-status="{p['testStatus']}" data-name="{esc(p['brand']+' '+p['name'])}"><div class="product-photo type-{p['type']}">{visual}</div><div class="product-body"><span class="product-kicker">{esc(p['brand'])}</span><h3>{esc(p['name'])}</h3><p class="product-summary">{esc(p['summary'])}</p><span class="test-status">{esc(statuses[p['testStatus']])}</span>{evidence}<ul class="product-features">{feats}</ul>{details}<a class="button purchase-link" href="{esc(destination)}" rel="{rel}" data-product-id="{p['id']}" data-placement="{placement}" data-affiliate="{str(purchase['affiliate']).lower()}" aria-label="View {esc(p['brand']+' '+p['name'])} at {esc(p['brand'])}">View at {esc(p['brand'])} <span aria-hidden="true">↗</span></a><span class="purchase-note">{'Affiliate link' if purchase['affiliate'] else 'Manufacturer purchase page'} · Check current price & availability</span></div></article>'''
intro=hero('Find your fit.<br>Keep your voice close.','A practical guide to earbuds and headsets for nearby conversation. Compare documented features, choose for your setting, and check the fit on your own phone.','The equipment guide','Earbuds & headsets')
cat_buttons='<button type="button" class="category-button active" data-category="all" aria-pressed="true">All candidates</button>'+''.join(f'<button type="button" class="category-button" data-category="{id}" aria-pressed="false">{esc(name)}</button>' for id,name in categories.items())
affiliate_products=[p for p in products if p['purchase']['affiliate']]
disclosure='Links below currently go directly to manufacturers and are not affiliate links. If we add an approved affiliate link, it will be labeled; we may earn a commission from a qualifying purchase. Compensation is not evidence of Vocari compatibility.'
if affiliate_products: disclosure='Links labeled affiliate may earn us a commission from qualifying purchases. Other links are ordinary manufacturer or retailer links. Compensation is not evidence of Vocari compatibility.'
if any(str(p['purchase'].get('network','')).lower()=='amazon' for p in affiliate_products): disclosure+=' As an Amazon Associate I earn from qualifying purchases.'
empty_note='Try another style or reset the filters.'
if not any(p['testStatus']=='tested' for p in products): empty_note+=' No candidate has completed our full Vocari test process yet.'
catalog=f'''<section class="section compact" id="products"><div class="wrap"><div class="catalog-intro"><div><span class="pill">{len(products)} researched candidates</span><p>These are candidates, not certified Vocari recommendations. Manufacturer Bluetooth calling support does not prove compatibility with your phone or Vocari.</p></div><a class="text-link" href="#compatibility">What to look for <span aria-hidden="true">↓</span></a></div><div class="catalog-controls" hidden><fieldset class="category-fieldset"><legend class="sr-only">Choose a use category</legend><div class="category-buttons">{cat_buttons}</div></fieldset><div class="filter-bar"><label class="search-label">Find a model<input type="search" id="product-search" placeholder="Search brand or model…" autocomplete="off"></label><label>Style<select id="type-filter"><option value="all">All styles</option>{''.join(f'<option value="{id}">{esc(name)}</option>' for id,name in types.items())}</select></label><label>Testing status<select id="status-filter"><option value="all">All candidates</option><option value="untested">Untested with Vocari</option><option value="tested">Completed Vocari testing</option><option value="limited">Limited test evidence</option></select></label><label>Order<select id="sort-filter"><option value="name">Brand, A–Z</option><option value="reverse">Brand, Z–A</option></select></label><button id="clear-filters" class="clear-button" type="button">Reset</button></div></div><div class="catalog-meta"><p id="result-count" role="status" aria-live="polite">{len(products)} candidates</p><span>Alphabetical order · No performance ranking</span></div><p class="disclosure-inline" id="disclosure">{esc(disclosure)}</p><noscript><p class="notice">All candidates are shown below. Search and filters are available with JavaScript enabled.</p></noscript><div class="product-grid" id="product-grid">{''.join(product_card(p) for p in products)}</div><div class="empty-state" id="empty-state" hidden><h2>No candidates match.</h2><p>{esc(empty_note)}</p><button class="button secondary" data-reset type="button">Show all candidates</button></div></div></section>'''
guide='''<section class="section dark-section" id="compatibility"><div class="wrap"><div class="section-heading"><div><span class="eyebrow">Buy for the conversation</span><h2>Music specs don’t tell<br>the whole story.</h2></div><p style="color:#b4c5d9">Vocari needs a working microphone and playback at the same time. That’s the Bluetooth call path, not just music playback.</p></div><div class="compatibility-grid"><article><span>01</span><h3>Start with Bluetooth calling.</h3><p>Look for a microphone and Hands-Free Profile (HFP). Then try both sides of a conversation on your actual phone. Wired audio and listen-only models are outside the current support scope.</p></article><article><span>02</span><h3>Separate the noise features.</h3><p>Listening ANC changes what you hear. Microphone noise suppression changes outgoing voice. Neither guarantees clearer Vocari audio, and neither is a hearing-protection rating.</p></article><article><span>03</span><h3>Choose for your environment.</h3><p>Open-ear designs, sealed earbuds and rated protectors serve different needs. Where protection is required, check the exact rating, fit and workplace rules.</p></article></div><p class="comparison-note" style="color:#b4c5d9">Vocari is not an emergency or safety-critical communication system. A headset’s NRR is a laboratory rating, not a promise of the attenuation an individual will achieve.</p></div></section><section class="section" id="method"><div class="wrap faq-split"><div><span class="eyebrow">Evidence before endorsement</span><h2>What a Vocari<br>test should cover.</h2><p class="muted">We’ll publish results when the evidence supports them. No star ratings or speed claims stand in for a two-person test.</p><a class="text-link" href="mailto:feedback@scalarlabs.ai?subject=Vocari%20headset%20feedback">Share your headset experience ↗</a></div><div class="faq-list"><details><summary>Microphone and playback, both directions</summary><div>Record the exact headset model, phone, operating system, app version and connection method. Check that each person hears the other through the personal-audio route, with no handset fallback.</div></details><details><summary>Delay, clarity and connection behavior</summary><div>Evaluate the complete path from one person’s headset microphone to the other person’s earpiece. Record measurements and conditions, then test reconnecting, movement and screen-off use. A music or gaming latency claim is not a Vocari measurement.</div></details><details><summary>Comfort and environmental fit</summary><div>Fit, microphone position, surrounding noise and protective equipment can change the experience. Any published result needs those conditions and its limitations, not just a pass/fail label.</div></details><details><summary>What does “untested” mean here?</summary><div>The product has not completed a documented Vocari compatibility evaluation for publication. Its features come from manufacturer sources. It is a research candidate, and no “Works with Vocari” certification is implied.</div></details></div></div></section>'''
page('/earbuds/','Earbuds & headset guide','Explore Bluetooth earbuds, boom-mic headsets, and rated hearing protection. Compare features and purchase directly, with honest Vocari testing status.',intro+catalog+guide,'/earbuds/',extra='<link rel="stylesheet" href="/earbuds/styles.css"><script src="/earbuds/app.js" defer></script>')
